   101    {
   102      hb_blob_t *maxp_blob = hb_sanitize_context_t().reference_table<maxp> (plan->source);
   103      hb_blob_t *maxp_prime_blob = hb_blob_copy_writable_or_fail (maxp_blob);
   104      hb_blob_destroy (maxp_blob);
   105
   106      if (unlikely (!maxp_prime_blob)) {
   107        return false;
   108      }
   109      maxp *maxp_prime = (maxp *) hb_blob_get_data (maxp_prime_blob, nullptr);
   110
   111      maxp_prime->set_num_glyphs (plan->glyphs.len);
   112      if (plan->drop_hints)
   113        drop_hint_fields (plan, maxp_prime);
   114
   115      bool result = plan->add_table (HB_OT_TAG_maxp, maxp_prime_blob);
   116      hb_blob_destroy (maxp_prime_blob);
   117      return result;
   118    }
